import { useState } from "react";
import { Box, Button, Menu, MenuItem } from "@mui/material";

const COLORS = ["#FF5733", "#33FF57", "#3357FF", "#F3FF33", "#FF33A8", "#33FFF3"];

const MangeLayout = () => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [selectedColor, setSelectedColor] = useState(COLORS[0]);

  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = (color) => {
    setAnchorEl(null);
    if (color) {
      setSelectedColor(color);
      document.documentElement.style.setProperty("--main-bg", color);
    }
  };

  return (
    <Box sx={{ p: 2, textAlign: "center" }}>
      <Button variant="contained" onClick={handleClick} sx={{ backgroundColor: selectedColor }}>
        Change Theme Color
      </Button>
      <Menu anchorEl={anchorEl} open={Boolean(anchorEl)} onClose={() => handleClose()}>
        {COLORS.map((color, index) => (
          <MenuItem
            key={index}
            onClick={() => handleClose(color)}
            sx={{ backgroundColor: color, color: "#fff", "&:hover": { opacity: 0.8 } }}
          >
            {color}
          </MenuItem>
        ))}
      </Menu>
    </Box>
  );
};

export default MangeLayout;
